<template><el-button size="small" type="primary" @click="open">{{purchase?'分批入库':leader?'放行本批':'分批备货'}}</el-button><el-dialog v-model="visible" title="本批收发明细" width="760px" :close-on-click-modal="false"><el-alert title="本批数量可少于剩余数量，零表示本批不处理该商品；过账金额仅按本批计算。备货将预占库存，最终放行后扣减。" type="info" :closable="false" /><el-table :data="items" border style="margin-top:16px"><el-table-column prop="product_name" label="商品" min-width="150" /><el-table-column prop="quantity" label="订单数量" width="100" /><el-table-column label="已完成" width="100"><template #default="{row}">{{purchase?row.received_qty:row.shipped_qty}}</template></el-table-column><el-table-column label="本批数量" width="180"><template #default="{row}"><el-input-number v-model="row.batch_qty" :min="0" :max="row.quantity-(purchase?row.received_qty:row.shipped_qty)" :precision="0" :disabled="!purchase&&leader" /></template></el-table-column><el-table-column v-if="purchase" label="生产批次与日期" min-width="280"><template #default="{row}"><template v-if="row.batch_enabled"><el-input v-model="row.lot_no" placeholder="批次号" /><el-date-picker v-model="row.manufactured_on" type="date" value-format="YYYY-MM-DD" placeholder="生产日期" /><el-date-picker v-model="row.expires_on" type="date" value-format="YYYY-MM-DD" placeholder="有效期" /></template><span v-else>无需批次</span></template></el-table-column></el-table><el-input v-model="company" placeholder="物流公司" style="margin-top:16px" /><el-input v-model="tracking" placeholder="物流单号" style="margin-top:8px" /><template #footer><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">确认本批</el-button></template></el-dialog></template>
<script setup lang="ts">
import { newRequestId } from '@/utils/requestId'
import {ref} from 'vue'
import {get,post} from '@/utils/request'
import {ElMessage} from 'element-plus'
const props=defineProps<{id:number;warehouse:number;purchase:boolean;leader:boolean}>(),emit=defineEmits<{changed:[]}>(),visible=ref(false),saving=ref(false),items=ref<any[]>([]),company=ref(''),tracking=ref(''),key=ref('')
async function open(){try{const r=await get<any[]>(props.purchase?'/purchaseorderitems':'/salesorderitems',{filter:JSON.stringify({order_id:props.id})});items.value=(r.data||[]).map(x=>({...x,received_qty:Number(x.received_qty||0),shipped_qty:Number(x.shipped_qty||0),batch_qty:!props.purchase&&props.leader?Number(x.pending_qty||0):x.quantity-Number((props.purchase?x.received_qty:x.shipped_qty)||0)}));key.value=newRequestId();company.value='';tracking.value='';visible.value=true}catch{}}
async function submit(){if(!props.warehouse){ElMessage.warning('请先选择实际处理仓库');return}saving.value=true;try{await post('/orders/batch',{type:props.purchase?'purchase':'sales',step:props.purchase?'receive':props.leader?'release':'prepare',order_id:props.id,warehouse_id:props.warehouse,items:items.value.map(x=>({product_id:x.product_id,quantity:x.batch_qty,lot_no:x.lot_no,manufactured_on:x.manufactured_on,expires_on:x.expires_on})),logistics_company:company.value,logistics_no:tracking.value,request_id:key.value});visible.value=false;ElMessage.success('本批处理成功');emit('changed')}catch{}finally{saving.value=false}}
</script>
